inline const simddouble scalar_cmp_pd(const simddouble& a, const simddouble& b, int imm)
{
	switch (imm)
	{
	case _CMP_EQ_OQ:
		return a == b ? 1.0 : 0.0;
	case _CMP_LT_OQ:
		return a < b ? 1.0 : 0.0;
	case _CMP_LE_OQ:
		return a <= b ? 1.0 : 0.0;
	case _CMP_GT_OQ:
		return a > b ? 1.0 : 0.0;
	case _CMP_GE_OQ:
		return a >= b ? 1.0 : 0.0;
	default:
		throw std::invalid_argument("Invalid comparison mode");
	}
}


