	// Operator to access elements like an array
	inline simdfloat& operator[](int index)
	{
		// Use a switch to return the correct element
		switch (index)
		{
		case 0:
			return x;
		case 1:
			return y;
		default:
			throw std::out_of_range("Index out of range");
		}
	}

	inline vec2 operator=(const vec2& _f)
	{
		x = _f.x;
		y = _f.y;
		return *this;
	}
