inline std::ostream& operator<<(std::ostream& _os, const simddmask& _v)
{
	alignas(64) double arr[8];
	simd_store_double(arr, _v);
	for (int i = 0; i < halfsimdwidth; i++)
	{
		_os << arr[i];
		if (i < halfsimdwidth - 1) _os << ", ";
	}
	return _os;
}
#endif
