{
	return simd_sqrt_double(simd_add_double(simd_mul_double(simd_sub_double(_a.x, _b.x), simd_sub_double(_a.x, _b.x)), simd_mul_double(simd_sub_double(_a.y, _b.y), simd_sub_double(_a.y, _b.y))));
}

