{
#ifndef __GNUC__
	return simd_tan_double(_x);
#else
	alignas(64) double tempTab[halfsimdwidth];
	simd_store_double(tempTab, _x);
	for (int i = 0; i < halfsimdwidth; i++)
	{
		tempTab[i] = tanf(tempTab[i]);
	}
	return simd_load_double(tempTab);
#endif
}
