inline int maskAll(const simdmask& _mask)
{
#ifdef USE_AVX2
	int maxmask = 0xFF;
#elif defined(USE_SSE41)
		int maxmask = 0xF;
#endif
	if (simd_movemask_float(_mask) == maxmask)
		return 1;
	else
		return 0;
}

